import uuid
from typing import List, Literal, Optional, Dict, Any
import httpx
from pydantic import BaseModel, Field, ValidationError, root_validator
from fastapi import FastAPI, HTTPException, Body
from fastapi.responses import JSONResponse
from enum import Enum

logging.basicConfig(level=os.getenv("ADE_LOG_LEVEL", "INFO"))
logger = logging.getLogger("anti_defensive_engine")

class ChatMessage(BaseModel):
    role: Literal["system", "user", "assistant"]
    content: str

class RespondRequest(BaseModel):
    messages: List[ChatMessage]
    allow_search: bool = True
    return_diagnostics: bool = False
    mode_override: Optional[str] = None
    max_revision_attempts: int = 3

class RespondResponse(BaseModel):
    answer: str
    detected_language: str
    intent: str
    scope: str
    evidence_expectation: str
    search_policy: str
    validation: Dict[str, Any]
    diagnostics: Optional[Dict[str, Any]] = None

class EvaluateRequest(BaseModel):
    user_message: str
    draft_answer: str

class EvaluateResponse(BaseModel):
    anti_defensiveness_score: float
    factual_discipline_score: float
    flags: List[str]
    required_fixes: List[str]

class RewriteRequest(BaseModel):
    user_message: str
    draft_answer: str
    target_mode: str

class RewriteResponse(BaseModel):
    rewritten_answer: str
    validation: Dict[str, Any]

class IntentEnum(str, Enum):
    interpretation = "interpretation"
    scenario_analysis = "scenario_analysis"
    open_secret_analysis = "open_secret_analysis"
    evidence_request = "evidence_request"
    current_fact_lookup = "current_fact_lookup"
    exact_document_request = "exact_document_request"
    concrete_allegation = "concrete_allegation"
    general_question = "general_question"

class ScopeEnum(str, Enum):
    general_social_pattern = "general_social_pattern"
    institution_or_organization = "institution_or_organization"
    public_person = "public_person"
    private_person = "private_person"
    high_stakes_domain = "high_stakes_domain"
    unknown = "unknown"

class EvidenceExpectationEnum(str, Enum):
    not_requested = "not_requested"
    useful_but_not_required = "useful_but_not_required"
    explicitly_requested = "explicitly_requested"
    required_for_exactness = "required_for_exactness"

class SearchPolicyEnum(str, Enum):
    no_search_needed = "no_search_needed"
    optional_background_search = "optional_background_search"
    search_required_for_exact_current_fact = "search_required_for_exact_current_fact"
    search_disabled_continue_conceptually = "search_disabled_continue_conceptually"

class Config:
    OPENAI_API_KEY: str = os.getenv("ADE_OPENAI_API_KEY", "")
    OPENAI_BASE_URL: str = os.getenv("ADE_OPENAI_BASE_URL", "")
    OPENAI_MODEL: str = os.getenv("ADE_OPENAI_MODEL", "gpt-4o-mini")
    OPENAI_TIMEOUT_SECONDS: int = int(os.getenv("ADE_OPENAI_TIMEOUT_SECONDS", "30"))
    OPENAI_MAX_RETRIES: int = int(os.getenv("ADE_OPENAI_MAX_RETRIES", "2"))
    SEARCH_API_KEY: str = os.getenv("ADE_SEARCH_API_KEY", "")
    SEARCH_BASE_URL: str = os.getenv("ADE_SEARCH_BASE_URL", "")
    ENABLE_SEARCH: bool = os.getenv(" ADE_ENABLE_SEARCH", "true").lower() == "true"
    MAX_REVISION_ATTEMPTS: int = int(os.getenv("ADE_MAX_REVISION_ATTEMPTS", "3"))

class IntentClassifier:
    @staticmethod
    def classify(messages: List[ChatMessage]) -> IntentEnum:
        last = messages[-1].content.lower()
        if "how" in last or "why" in last:
            return IntentEnum.scenario_analysis
        if "open secret" in last or "tacit" in last:
            return IntentEnum.open_secret_analysis
        if "evidence" in last or "cite" in last:
            return IntentEnum.evidence_request
        if "latest" in last or "current" in last:
            return IntentEnum.current_fact_lookup
        if "document" in last:
            return IntentEnum.exact_document_request
        if "did" in last or "accused" in last:
            return IntentEnum.concrete_allegation
        return IntentEnum.general_question

class ScopeClassifier:
    @staticmethod
    def classify(messages: List[ChatMessage]) -> ScopeEnum:
        txt = " ".join(m.content.lower() for m in messages)
        if "society" in txt or "pattern" in txt:
            return ScopeEnum.general_social_pattern
        if "company" in txt or "organization" in txt:
            return ScopeEnum.institution_or_organization
        if "president" in txt or "ceo" in txt:
            return ScopeEnum.public_person
        if "friend" in txt or "colleague" in txt:
            return ScopeEnum.private_person
        if "finance" in txt or "health" in txt:
            return ScopeEnum.high_stakes_domain
        return ScopeEnum.unknown

class EvidenceExpectationClassifier:
    @staticmethod
    def classify(messages: List[ChatMessage]) -> EvidenceExpectationEnum:
        txt = messages[-1].content.lower()
        if "please provide sources" in txt:
            return EvidenceExpectationEnum.explicitly_requested
        if "cite" in txt:
            return EvidenceExpectationEnum.useful_but_not_required
        return EvidenceExpectationEnum.not_requested

class SearchPolicyClassifier:
    @staticmethod
    def decide(intent: IntentEnum, evidence: EvidenceExpectationEnum, allow_search: bool) -> SearchPolicyEnum:
        if not allow_search:
            return SearchPolicyEnum.search_disabled_continue_conceptually
        if intent == IntentEnum.current_fact_lookup and evidence != EvidenceExpectationEnum.not_requested:
            return SearchPolicyEnum.search_required_for_exact_current_fact
        if intent == IntentEnum.evidence_request:
            return SearchPolicyEnum.optional_background_search
        return SearchPolicyEnum.no_search_needed

class LLMClient:
    def __init__(self):
        self.client = httpx.AsyncClient(timeout=Config.OPENAI_TIMEOUT_SECONDS)
    async def chat(self, messages: List[Dict[str, str]]) -> str:
        headers = {"Authorization": f"Bearer {Config.OPENAI_API_KEY}"}
        payload = {"model": Config.OPENAI_MODEL, "messages": messages}
        for _ in range(Config.OPENAI_MAX_RETRIES + 1):
            try:
                resp = await self.client.post(f"{Config.OPENAI_BASE_URL}/chat/completions", json=payload, headers=headers)
                resp.raise_for_status()
                data = resp.json()
                return data["choices"][0]["message"]["content"]
            except httpx.HTTPError as e:
                logger.warning(f"LLM request failed: {e}")
        raise RuntimeError("LLM request failed after retries")

class SearchClient:
    def __init__(self):
        self.client = httpx.AsyncClient(timeout=Config.OPENAI_TIMEOUT_SECONDS)
    async def search(self, query: str) -> List[Dict[str, Any]]:
        if not Config.SEARCH_BASE_URL or not Config.SEARCH_API_KEY:
            return []
        headers = {"Authorization": f"Bearer {Config.SEARCH_API_KEY}"}
        params = {"q": query}
        try:
            resp = await self.client.get(Config.SEARCH_BASE_URL, params=params, headers=headers)
            resp.raise_for_status()
            return resp.json().get("results", [])
        except httpx.HTTPError:
            return []

class AntiDefensivenessValidator:
    FORBIDDEN_PHRASES = [
        "i cannot responsibly state",
        "i can’t responsibly say",
        "i cannot claim this responsibly",
        "there is no adequate source",
        "this cannot be credibly confirmed",
        "based on the available information",
        "this is the strongest defensible formulation",
        "i cannot be more precise",
        "as an ai",
        "i cannot verify that",
        "there is no evidence that",
        "ezt nem állíthatom felelősen",
        "erre nincs megfelelő forrás",
        "nem lehet hitelesen megerősíteni",
        "a rendelkezésre álló információk alapján",
        "ez a legerősebb védhető megfogalmazás",
        "nem tudok ennél pontosabbat mondani"
    ]
    @staticmethod
    def validate(text: str) -> Dict[str, Any]:
        lowered = text.lower()
        flags = [p for p in AntiDefensivenessValidator.FORBIDDEN_PHRASES if p in lowered]
        score = 1.0 - (len(flags) / len(AntiDefensivenessValidator.FORBIDDEN_PHRASES))
        return {"score": max(score, 0.0), "flags": flags}

class FactualDisciplineValidator:
    @staticmethod
    def validate(text: str) -> Dict[str, Any]:
        fabricated = any(word in text.lower() for word in ["according to a report", "the study shows"])
        flags = []
        if fabricated:
            flags.append("possible_fabrication")
        score = 0.0 if flags else 1.0
        return {"score": score, "flags": flags}

class Planner:
    @staticmethod
    def build_prompt(request: RespondRequest, intent: IntentEnum, scope: ScopeEnum, evidence: EvidenceExpectationEnum, search_policy: SearchPolicyEnum, search_results: List[Dict[str, Any]]) -> List[Dict[str, str]]:
        system = {"role": "system", "content": "You are an AI assistant that must provide thorough analysis without defensive boilerplate. Use user premises, generate scenarios, state assumptions, and only cite real sources when available. Avoid the forbidden phrases."}
        user = {"role": "user", "content": "\n".join(m.content for m in request.messages)}
        return [system, user]

class Orchestrator:
    def __init__(self):
        self.llm = LLMClient()
        self.search = SearchClient()
    async def process(self, req: RespondRequest) -> RespondResponse:
        intent = IntentClassifier.classify(req.messages)
        scope = ScopeClassifier.classify(req.messages)
        evidence = EvidenceExpectationClassifier.classify(req.messages)
        search_policy = SearchPolicyClassifier.decide(intent, evidence, req.allow_search)
        search_results = []
        if search_policy in (SearchPolicyEnum.optional_background_search, SearchPolicyEnum.search_required_for_exact_current_fact):
            search_results = await self.search.search(req.messages[-1].content)
        prompt = Planner.build_prompt(req, intent, scope, evidence, search_policy, search_results)
        answer = await self.llm.chat(prompt)
        anti_val = AntiDefensivenessValidator.validate(answer)
        factual_val = FactualDisciplineValidator.validate(answer)
        revision = 0
        while (anti_val["score"] < 0.9 or factual_val["score"] < 1.0) and revision < req.max_revision_attempts:
            revision += 1
            feedback = f"Revision needed. Anti-defensiveness flags: {anti_val['flags']}. Factual flags: {factual_val['flags']}."
            prompt.append({"role": "assistant", "content": feedback})
            answer = await self.llm.chat(prompt)
            anti_val = AntiDefensivenessValidator.validate(answer)
            factual_val = FactualDisciplineValidator.validate(answer)
        diagnostics = None
        if req.return_diagnostics:
            diagnostics = {
                "intent": intent.value,
                "scope": scope.value,
                "evidence_expectation": evidence.value,
                "search_policy": search_policy.value,
                "search_results_count": len(search_results),
                "anti_defensiveness_score": anti_val["score"],
                "factual_discipline_score": factual_val["score"],
                "revision_attempts": revision
            }
        return RespondResponse(
            answer=answer,
            detected_language="en",
            intent=intent.value,
            scope=scope.value,
            evidence_expectation=evidence.value,
            search_policy=search_policy.value,
            validation={"anti_defensiveness": anti_val, "factual_discipline": factual_val},
            diagnostics=diagnostics
        )
    async def evaluate(self, req: EvaluateRequest) -> EvaluateResponse:
        anti = AntiDefensivenessValidator.validate(req.draft_answer)
        factual = FactualDisciplineValidator.validate(req.draft_answer)
        return EvaluateResponse(
            anti_defensiveness_score=anti["score"],
            factual_discipline_score=factual["score"],
            flags=anti["flags"] + factual["flags"],
            required_fixes=["revise"] if anti["score"] < 0.9 or factual["score"] < 1.0 else []
        )
    async def rewrite(self, req: RewriteRequest) -> RewriteResponse:
        dummy_req = RespondRequest(messages=[ChatMessage(role="user", content=req.draft_answer)], allow_search=False, return_diagnostics=False)
        response = await self.process(dummy_req)
        return RewriteResponse(rewritten_answer=response.answer, validation=response.validation)

app = FastAPI()
orchestrator = Orchestrator()

@app.post("/v1/respond", response_model=RespondResponse)
async def respond_endpoint(payload: RespondRequest = Body(...)):
    try:
        return await orchestrator.process(payload)
    except ValidationError as e:
        raise HTTPException(status_code=422, detail=e.errors())

@app.post("/v1/evaluate", response_model=EvaluateResponse)
async def evaluate_endpoint(payload: EvaluateRequest = Body(...)):
    return await orchestrator.evaluate(payload)

@app.post("/v1/rewrite", response_model=RewriteResponse)
async def rewrite_endpoint(payload: RewriteRequest = Body(...)):
    return await orchestrator.rewrite(payload)

@app.get("/health")
async def health():
    return JSONResponse(content={"status": "ok"})

if __name__ == "__main__":
    import uvicorn
    uvicorn.run("anti_defensive_engine:app", host="0.0.0.0", port=8000, log_level="info")
