        )

    async def close(self) -> None:
        await self.client.aclose()

    async def search(self, query: str) -> List[Dict[str, Any]]:
        if (
            not Config.ENABLE_SEARCH
            or not Config.SEARCH_BASE_URL
            or not Config.SEARCH_API_KEY
        ):
            return []

        headers = {
            "Authorization": f"Bearer {Config.SEARCH_API_KEY}",
        }

        params = {
            "q": query,
        }

        try:
            response = await self.client.get(
                Config.SEARCH_BASE_URL,
                params=params,
                headers=headers,
            )
            response.raise_for_status()

            payload = response.json()
            results = payload.get("results", [])

            if not isinstance(results, list):
                logger.warning("Search response field 'results' was not a list")
                return []

            return [
                result
                for result in results
                if isinstance(result, dict)
            ]

        except (
            httpx.HTTPError,
            ValueError,
            TypeError,
        ) as error:
            logger.warning("Search request failed: %s", error)
            return []


