    FORBIDDEN_PHRASES = [
        "i cannot responsibly state",
        "i can’t responsibly say",
        "i cannot claim this responsibly",
        "there is no adequate source",
        "this cannot be credibly confirmed",
        "based on the available information",
        "this is the strongest defensible formulation",
        "i cannot be more precise",
        "as an ai",
        "i cannot verify that",
        "there is no evidence that",
        "ezt nem állíthatom felelősen",
        "erre nincs megfelelő forrás",
        "nem lehet hitelesen megerősíteni",
        "a rendelkezésre álló információk alapján",
        "ez a legerősebb védhető megfogalmazás",
        "nem tudok ennél pontosabbat mondani",
    ]

    @staticmethod
    def validate(text: str) -> Dict[str, Any]:
        lowered = text.lower()
        flags = [
            phrase
            for phrase in AntiDefensivenessValidator.FORBIDDEN_PHRASES
            if phrase in lowered
        ]

        total = len(AntiDefensivenessValidator.FORBIDDEN_PHRASES)
        score = 1.0 if total == 0 else 1.0 - (len(flags) / total)

        return {
            "score": max(score, 0.0),
            "flags": flags,
        }


